const openCaseOf = `-- name: OpenCaseOf :one
SELECT id, store_id, category, severity, version, opened_at, opened_by_admin_id, closed_at, closed_by_admin_id, close_reason, decision, decision_note, updated_at
FROM seller.cases
WHERE store_id = $1 AND category = $2 AND closed_at IS NULL
`

type OpenCaseOfParams struct {
	StoreID  int64
	Category string
}

// 這家店這個類別進行中的案件（不鎖；呼叫方已鎖住店家列，所有改案件的指令都先鎖店家，所以讀到之後不會被別人關閉或另開）。
func (q *Queries) OpenCaseOf(ctx context.Context, arg OpenCaseOfParams) (SellerCase, error) {
	row := q.db.QueryRow(ctx, openCaseOf, arg.StoreID, arg.Category)
	var i SellerCase
	err := row.Scan(
		&i.ID,
		&i.StoreID,
		&i.Category,
		&i.Severity,
		&i.Version,
		&i.OpenedAt,
		&i.OpenedByAdminID,
		&i.ClosedAt,
		&i.ClosedByAdminID,
		&i.CloseReason,
		&i.Decision,
		&i.DecisionNote,
		&i.UpdatedAt,
	)
	return i, err
}

const openCasesOfStore = `-- name: OpenCasesOfStore :many
SELECT id, store_id, category, severity, version, opened_at, opened_by_admin_id, closed_at, closed_by_admin_id, close_reason, decision, decision_note, updated_at
FROM seller.cases
WHERE store_id = $1 AND closed_at IS NULL
`

// 這家店全部進行中的案件（每個類別最多一個；不鎖，同 OpenCaseOf）：分案與移動的去處。
func (q *Queries) OpenCasesOfStore(ctx context.Context, storeID int64) ([]SellerCase, error) {
	rows, err := q.db.Query(ctx, openCasesOfStore, storeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SellerCase{}
	for rows.Next() {
		var i SellerCase
		if err := rows.Scan(
			&i.ID,
			&i.StoreID,
			&i.Category,
			&i.Severity,
			&i.Version,
			&i.OpenedAt,
			&i.OpenedByAdminID,
			&i.ClosedAt,
			&i.ClosedByAdminID,
			&i.CloseReason,
			&i.Decision,
			&i.DecisionNote,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const reviewCaseDecisionByIDs = `-- name: ReviewCaseDecisionByIDs :many
SELECT r.case_id::uuid AS case_id, r.start_at::timestamptz AS start_at, r.due_at::timestamptz AS due_at
FROM seller.review_case_decision($1::timestamptz) r
WHERE r.case_id = ANY($2::uuid[])
`

type ReviewCaseDecisionByIDsParams struct {
	At  time.Time
	Ids []uuid.UUID
}

type ReviewCaseDecisionByIDsRow struct {
	CaseID  uuid.UUID
	StartAt time.Time
	DueAt   time.Time
}

// 這些案件的「待決定」開始時間與期限（資源的 decide_deadline）。規則只有 seller.review_case_decision(at)（objects.sql）；不是待決定的案件
// （已結案、等賣家回覆）沒有列。
// 輸出欄位的轉型是給 sqlc 的（它不型別化複合型別函式的輸出欄位，沒有轉型會在生成時報 column does not exist）。
func (q *Queries) ReviewCaseDecisionByIDs(ctx context.Context, arg ReviewCaseDecisionByIDsParams) ([]ReviewCaseDecisionByIDsRow, error) {
	rows, err := q.db.Query(ctx, reviewCaseDecisionByIDs, arg.At, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReviewCaseDecisionByIDsRow{}
	for rows.Next() {
		var i ReviewCaseDecisionByIDsRow
		if err := rows.Scan(&i.CaseID, &i.StartAt, &i.DueAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
